"""Synthetic evidence generated by the real read model; never host telemetry."""
from datetime import datetime, timedelta, timezone
from megalodon.dashboard_traffic import TrafficDashboardStore


def finding_evidence_fixture():
    """Keep observation, detection and read time independent and bytes exact."""
    observed = datetime(2026, 9, 17, 12, tzinfo=timezone.utc)
    rows = []
    for index in range(3):
        at = observed + timedelta(seconds=index * 10)
        rows.append(dict(kind="event", record_id=index + 1, timestamp=at.isoformat(),
            src_ip="192.0.2.1", dst_ip="198.51.100.1", protocol="TCP", src_port=12345,
            dst_port=443, tcp_flags='["SYN"]', byte_count=2**63 - 1, run_id=1,
            source="jsonl", run_status="completed", receipt_version=3,
            termination_reason="source_exhausted"))
        if index != 2:
            rows.append(dict(kind="finding", record_id=index + 1, event_id=index + 1,
                timestamp=(at + timedelta(seconds=2)).isoformat(), rule_id="PORT_SCAN",
                severity="MEDIUM"))
    return TrafficDashboardStore._project(rows)
